hw2：Todo List
前端實作目標功能： 新增功能：add 刪除功能：delete 編輯功能：update 更新狀態功能：checked / unchecked 切換列表：All / Active / Completed 清除所有 todo：Clear
以上功能只要利用前端就能達成，程式碼如下： 前端介面&lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt; &lt;title&gt;Week12 Todo List&lt;/title&gt; &lt;script src=&quot;https://code.jquery.com/jquery-3.5.1.js&quot;&gt;&lt;/script&gt; &lt;link rel=&quot;stylesheet&quot; href=&quot;https://stackpath.bootstrapcdn.com/bootstrap/4.5.2/css/bootstrap.min.css&quot; integrity=&quot;sha384-JcKb8q3iqJ61gNV9KGb8thSsNjpSL0n8PARn9HuZOnIxN0hoP+VmmDGMN5t9UJ0Z&quot; crossorigin=&quot;anonymous&quot;&gt; &lt;link rel=&quot;stylesheet&quot; href=&quot;css/style.css&quot;&gt;&lt;/head&gt;&lt;body&gt; &lt;div class=&quot;wrapper&quot;&gt; &lt;div class=&quot;todo__header&quot;&gt; &lt;button type=&quot;button&quot; class=&quot;btn btn-save&quot; href=&quot;#&quot;&gt;Save&lt;/button&gt; &lt;button type=&quot;button&quot; class=&quot;btn clear-all&quot; href=&quot;#&quot;&gt;Reset&lt;/button&gt; &lt;/div&gt; &lt;h1&gt;Todo List&lt;/h1&gt; &lt;div class=&quot;todo__input-block&quot;&gt; &lt;input class=&quot;todo__input&quot; type=&quot;text&quot; placeholder=&quot;Add New Todo Here...&quot; minlength=&quot;1&quot; maxlength=&quot;128&quot;&gt; &lt;button class=&quot;btn-new&quot;&gt;&lt;/button&gt; &lt;/div&gt; &lt;ul class=&quot;nav nav-middle justify-content-center todo__status&quot;&gt; &lt;li class=&quot;nav-item&quot;&gt; &lt;a class=&quot;nav-link active&quot; href=&quot;#&quot; data-filter=&quot;all&quot;&gt;All&lt;/a&gt; &lt;/li&gt; &lt;li class=&quot;nav-item&quot;&gt; &lt;a class=&quot;nav-link&quot; href=&quot;#&quot; data-filter=&quot;in-progress&quot;&gt;In Progress&lt;/a&gt; &lt;/li&gt; &lt;li class=&quot;nav-item&quot;&gt; &lt;a class=&quot;nav-link&quot; href=&quot;#&quot; data-filter=&quot;completed&quot;&gt;Completed&lt;/a&gt; &lt;/li&gt; &lt;/ul&gt; &lt;ul class=&quot;todo__list&quot;&gt; &lt;!-- 要新增 template 的區塊 --&gt; &lt;li class=&quot;todo&quot;&gt; &lt;input class=&quot;todo__check&quot; type=&quot;checkbox&quot; id=&quot;todo-0&quot;&gt; &lt;label class=&quot;todo__title&quot; for=&quot;todo&quot;&gt;Coding&lt;/label&gt; &lt;button class=&quot;btn-delete&quot;&gt;&lt;/button&gt; &lt;/li&gt; &lt;/ul&gt; &lt;/div&gt; &lt;/body&gt;&lt;/html&gt;
前端 JavaScript&lt;script&gt; let id = 1; const template = ` &lt;li class=&quot;todo&quot;&gt; &lt;input class=&quot;todo__check&quot; type=&quot;checkbox&quot; id=&quot;todo-&#123;id&#125;&quot;&gt; &lt;label class=&quot;todo__title&quot; for=&quot;todo-&#123;id&#125;&quot;&gt;&#123;content&#125;&lt;/label&gt; &lt;button class=&quot;btn-delete&quot;&gt;&lt;/button&gt; &lt;/li&gt; ` // 新增功能: 點擊 $(&#x27;.btn-new&#x27;).click(() =&gt; &#123; addTodo() &#125;); // 新增功能: 按 Enter $(&#x27;.todo__input&#x27;).keydown(e =&gt; &#123; if (e.key === &#x27;Enter&#x27;) &#123; addTodo() &#125; &#125;); // 刪除功能: 利用事件代理 $(&#x27;.todo__list&#x27;).on(&#x27;click&#x27;, &#x27;.btn-delete&#x27;, (e) =&gt; &#123; $(e.target).parent().remove(); &#125;); // 標記狀態: 已完成 / 未完成 $(&#x27;.todo__list&#x27;).on(&#x27;change&#x27;, &#x27;.todo__check&#x27;, (e) =&gt; &#123; const target = $(e.target); const isChecked = target.is(&quot;:checked&quot;); if (isChecked) &#123; target.parents(&#x27;.todo&#x27;).addClass(&#x27;checked&#x27;); &#125; else &#123; target.parents(&#x27;.todo&#x27;).removeClass(&#x27;checked&#x27;); &#125; &#125;); // 篩選 todo 狀態 $(&#x27;.todo__status&#x27;).on(&#x27;click&#x27;, &#x27;a&#x27;, e =&gt; &#123; const target = $(e.target); const filter = target.attr(&#x27;data-filter&#x27;); $(&#x27;.todo__status a.active&#x27;).removeClass(&#x27;active&#x27;); target.addClass(&#x27;active&#x27;); if (filter === &#x27;all&#x27;) &#123; $(&#x27;.todo&#x27;).show(); &#125; else if (filter === &#x27;in-progress&#x27;) &#123; $(&#x27;.todo&#x27;).show(); $(&#x27;.todo.checked&#x27;).hide(); &#125; else &#123; // completed $(&#x27;.todo&#x27;).hide(); $(&#x27;.todo.checked&#x27;).show(); &#125; &#125;); // 清除所有 todo $(&#x27;.clear-all&#x27;).click(() =&gt; &#123; $(&#x27;.todo&#x27;).remove(); &#125;); // 儲存 todo $(&#x27;.btn-save&#x27;).click(() =&gt; &#123; let todos = []; $(&#x27;.todo&#x27;).each((i, element) =&gt; &#123; const input = $(element).find(&#x27;.todo__check&#x27;); const label = $(element).find(&#x27;.todo__title&#x27;); todos.push(&#123; id: input.attr(&#x27;id&#x27;).replace(&#x27;todo-&#x27;, &#x27;&#x27;), // 把 todo-id 的 todo- 換成空字串 content: label.text(), isDone: $(element).hasClass(&#x27;checked&#x27;) &#125;); &#125;); JSON.stringify(todos); // 將 JS 物件轉換成 JSON 字串 &#125;); function addTodo() &#123; const value = $(&#x27;.todo__input&#x27;).val(); if (!value) return; $(&#x27;.todo__list&#x27;).prepend( template .replace(&#x27;&#123;content&#125;&#x27;, escape(value)) .replace(/&#123;id&#125;/g, id) ); id += 1; $(&#x27;.todo__input&#x27;).val(&#x27;&#x27;); &#125; function escape(toOutput) &#123; return toOutput .replace(/&amp;/g, &#x27;&amp;amp;&#x27;) .replace(/&lt;/g, &#x27;&amp;lt;&#x27;) .replace(/&gt;/g, &#x27;&amp;gt;&#x27;) .replace(/&quot;/g, &#x27;&amp;quot;&#x27;) .replace(/&#x27;/g, &#x27;&amp;#039;&#x27;); &#125;&lt;/script&gt;
前後端串接目標功能 儲存功能：Save
PHP API將前端得到的資料 JSON.stringify(todos)，利用 Ajax 方式 POST 到資料庫： // 儲存 todo$(&#x27;.btn-save&#x27;).click(() =&gt; &#123; let todos = []; $(&#x27;.todo&#x27;).each((i, element) =&gt; &#123; const input = $(element).find(&#x27;.todo__check&#x27;); const label = $(element).find(&#x27;.todo__title&#x27;); todos.push(&#123; id: input.attr(&#x27;id&#x27;).replace(&#x27;todo-&#x27;, &#x27;&#x27;), // 把 todo-id 的 todo- 換成空字串 content: label.text(), isDone: $(element).hasClass(&#x27;checked&#x27;) &#125;); &#125;); const data = JSON.stringify(todos); // 將 JS 物件轉換成 JSON 字串 $.ajax(&#123; type: &#x27;POST&#x27;, url: &#x27;http://localhost/heidi/week12_local/hw2/api_add_todo.php&#x27;, data: &#123; todo: data &#125;, success: function(resp) &#123; const respId = resp.id window.location = &#x27;index.html?id=&#x27; + respId; &#125;, error: function () &#123; alert(&#x27;Error!&#x27;); &#125; &#125;);&#125;);
如此即可利用前端 JavaScript 從後端拿取 JSON 格式的資料，並用 JSON.parse() 將 JSON 字串轉換成 JavaScript 物件： // URLSearchParams(): 解析網址參數const serchParams = new URLSearchParams(window.location.search); // ?id=...const todoId = serchParams.get(&#x27;id&#x27;);if (todoId) &#123; $.getJSON(&#x27;http://localhost/heidi/week12_local/hw2/api_get_todo.php?id=&#x27; + todoId, function (data) &#123; const todos = JSON.parse(data.data.todo); restoreTodos(todos); &#125;);&#125;
將拿到的資料再以 JS 處理新增到頁面，把模版 template 加上 content、id、todoClass： function restoreTodos(todos) &#123; if (todos.length === 0) return; // id 要從讀取的最後一個 todo id 繼續增加 id = todos[todos.length - 1].id + 1; for(let i = 0; i &lt; todos.length; i++) &#123; const todo = todos[i]; $(&#x27;.todo__list&#x27;).prepend( template .replace(&#x27;&#123;content&#125;&#x27;, escape(todo.content)) .replace(/&#123;id&#125;/g, todo.id) .replace(&#x27;&#123;todoClass&#125;&#x27;, todo.isDone ? &#x27;checked&#x27; : &#x27;&#x27;) ); &#125;&#125;
Single Page ApplicationSingle Page Application（單頁面應用程式），簡稱 SPA。是前端利用 Ajax 以非同步方式串接後端 API，如此可將前後端分離，在交換資料時不需換頁，可透過動態方式更新部分頁面。 而早期的網頁主要採用 Multiple Page Application（多頁式應用程式）設計，與 SPA 概念相對應，每次交換資料時都需換頁。 SPA 的優缺點優點 增進使用者體驗不需換頁即可載入新的資訊。例如 Gmail 或影音播放網站，可以在播放音樂的同時，繼續瀏覽網站其他資訊。 前後端分離後端只需負責制定 API 文件，提供前端資料。前端則利用 Ajax 從後端拿取資料，並以 JavaScript 在 html 動態產生內容。
缺點 SEO（搜尋引擎最佳化）較差由於 SPA 是利用 JavaScript 動態產生內容，檢視原始碼會發現原始內容是空的，解決方法：第一次頁面由 Server side render，之後的操作都改用 Client side render，就可以保證搜尋引擎也能爬到完整的 HTML。 前端工作複雜化原先是利用不同路由處理不同功能，改成由單一頁面統一管理，就像在網頁上實作 APP。 初次載入頁面費時初次瀏覽頁面時會需要下載 JavaScript 或是其他頁面的 template。
由後端負責提供只輸出資料的 API vs PHP 直接輸出內容後端負責提供只輸出資料的 API Server 端接收到請求，會回傳 JSON 或其他特定格式的資料給前端，瀏覽器再將資料動態更新至頁面 因為是動態產生資料，檢視原始碼會發現動態更新的內容是空的
PHP 直接輸出內容 Server 端接收到請求，會將所需資料與頁面經處理後回傳 html 檔給前端，瀏覽器透過重整頁面顯示 因此回傳的頁面，檢視原始碼是有包含資料的
